# --- Row-level security, grants, the platform view and audit_log partitions --------------
#
# Frozen with this revision on purpose: later revisions add their own grants and policies.
# Role names match assay_db.roles; the roles themselves are created by assay_db.roles.bootstrap.

TENANT_ID = "assay.current_tenant_id()"

# Tables the tenant path (app_tenant) reads and writes, one tenant at a time. No DELETE.
APP_TENANT_READ_WRITE = (
    "users",
    "batches",
    "documents",
    "document_events",
    "document_parts",
    "document_labels",
    "pages",
    "signature_check",
    "signers",
    "companion_loan_terms",
    "signing_events",
    "extracted_fields",
    "chat_conversations",
    "chat_audit",
    "ai_usage",
    "attachments",
    "faces",
    "face_matches",
    "fraud_scores",
)

# Every table except ai_models gets RLS enabled and forced (section 6, rule 5).
RLS_TABLES = (*APP_TENANT_READ_WRITE, "tenants", "tenant_models", "tenant_storage", "audit_log")

INGESTION_VIEW_DOCUMENT_COLUMNS = (
    "id",
    "tenant_id",
    "batch_id",
    "status",
    "error_code",
    "page_count",
    "size_bytes",
    "has_companion",
    "received_at",
    "completed_at",
)

CURRENT_TENANT_FUNCTION = """
CREATE FUNCTION assay.current_tenant_id() RETURNS uuid
LANGUAGE sql STABLE PARALLEL SAFE
AS $$ SELECT nullif(pg_catalog.current_setting('app.tenant_id', true), '')::uuid $$
"""

INGESTION_VIEW = """
CREATE VIEW platform.platform_ingestion_v WITH (security_barrier = true) AS
SELECT
    d.id AS document_id,
    d.tenant_id,
    t.name AS tenant_name,
    d.batch_id,
    d.status,
    d.error_code,
    d.page_count,
    d.size_bytes,
    d.has_companion,
    (
        SELECT count(*)
        FROM assay.document_parts p
        WHERE p.tenant_id = d.tenant_id AND p.document_id = d.id
    ) AS part_count,
    d.received_at,
    d.completed_at
FROM assay.documents d
JOIN assay.tenants t ON t.id = d.tenant_id
"""

AUDIT_PARTITION_FUNCTION = """
CREATE FUNCTION assay.ensure_audit_log_partitions(months_ahead integer DEFAULT 12)
RETURNS SETOF text
LANGUAGE plpgsql
AS $$
DECLARE
    first_day date;
    part_name text;
BEGIN
    FOR i IN 0..months_ahead LOOP
        first_day := (date_trunc('month', now() AT TIME ZONE 'UTC')
                      + make_interval(months => i))::date;
        part_name := 'audit_log_' || to_char(first_day, 'YYYY_MM');
        IF to_regclass('assay.' || quote_ident(part_name)) IS NULL THEN
            EXECUTE format(
                'CREATE TABLE assay.%I PARTITION OF assay.audit_log FOR VALUES FROM (%L) TO (%L)',
                part_name,
                first_day::timestamp AT TIME ZONE 'UTC',
                (first_day + interval '1 month')::timestamp AT TIME ZONE 'UTC'
            );
            RETURN NEXT part_name;
        END IF;
    END LOOP;
END
$$
"""


def _policy(
    name: str, table: str, command: str, role: str, *, using: str | None, check: str | None
) -> None:
    statement = f"CREATE POLICY {name} ON assay.{table} AS PERMISSIVE FOR {command} TO {role}"
    if using is not None:
        statement += f" USING ({using})"
    if check is not None:
        statement += f" WITH CHECK ({check})"
    op.execute(statement)


def _security_upgrade() -> None:
    # Fails closed: an unset or empty app.tenant_id gives NULL, which matches no row.
    op.execute(CURRENT_TENANT_FUNCTION)
    op.execute("REVOKE ALL ON FUNCTION assay.current_tenant_id() FROM PUBLIC")
    op.execute(
        "GRANT EXECUTE ON FUNCTION assay.current_tenant_id() TO app_tenant, audit_writer, tss"
    )

    op.execute("REVOKE ALL ON SCHEMA assay FROM PUBLIC")
    op.execute(
        "GRANT USAGE ON SCHEMA assay TO app_tenant, platform_reader, platform_writer, "
        "audit_writer, tss, platform_view_owner"
    )

    for table in RLS_TABLES:
        op.execute(f"ALTER TABLE assay.{table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE assay.{table} FORCE ROW LEVEL SECURITY")

    # app_tenant: one tenant at a time, the one named by SET LOCAL app.tenant_id.
    own = f"tenant_id = {TENANT_ID}"
    for table in (*APP_TENANT_READ_WRITE, "tenant_models"):
        _policy("app_tenant_own_tenant", table, "ALL", "app_tenant", using=own, check=own)
    own_id = f"id = {TENANT_ID}"
    _policy("app_tenant_own_tenant", "tenants", "ALL", "app_tenant", using=own_id, check=own_id)
    _policy("app_tenant_insert", "audit_log", "INSERT", "app_tenant", using=None, check=own)

    for table in APP_TENANT_READ_WRITE:
        op.execute(f"GRANT SELECT, INSERT, UPDATE ON assay.{table} TO app_tenant")
    op.execute("GRANT SELECT ON assay.tenants TO app_tenant")
    # Section 7b: the tenant admin selects the tenant's models.
    op.execute("GRANT UPDATE (extraction_model, answer_model) ON assay.tenants TO app_tenant")
    op.execute("GRANT SELECT ON assay.tenant_models TO app_tenant")
    op.execute("GRANT SELECT ON assay.ai_models TO app_tenant")
    op.execute("GRANT INSERT ON assay.audit_log TO app_tenant")

    # audit_writer (Cognito trigger Lambdas): INSERT on audit_log only, for the tenant it set.
    _policy("audit_writer_insert", "audit_log", "INSERT", "audit_writer", using=None, check=own)
    op.execute("GRANT INSERT ON assay.audit_log TO audit_writer")

    # tss: the only reader of tenant_storage, one tenant at a time.
    _policy("tss_own_tenant", "tenant_storage", "SELECT", "tss", using=own, check=None)
    op.execute("GRANT SELECT ON assay.tenant_storage TO tss")

    # platform_reader (admin routes): tenants and audit_log, plus the views in schema platform.
    for table in ("tenants", "audit_log"):
        _policy("platform_reader_all", table, "SELECT", "platform_reader", using="true", check=None)
        op.execute(f"GRANT SELECT ON assay.{table} TO platform_reader")

    # platform_writer (tenant provisioning, admin tenant changes). It writes tenant_storage but
    # cannot read it back, and inserts a new tenant's first admin into users.
    for table in ("tenants", "tenant_models"):
        _policy("platform_writer_all", table, "ALL", "platform_writer", using="true", check="true")
    for table in ("tenant_storage", "users", "audit_log"):
        _policy(
            "platform_writer_insert", table, "INSERT", "platform_writer", using=None, check="true"
        )
        op.execute(f"GRANT INSERT ON assay.{table} TO platform_writer")
    op.execute("GRANT SELECT, INSERT, UPDATE ON assay.tenants TO platform_writer")
    op.execute("GRANT SELECT, INSERT, UPDATE, DELETE ON assay.tenant_models TO platform_writer")
    op.execute("GRANT SELECT ON assay.ai_models TO platform_writer")

    # Schema platform holds the views the admin routes read. Each view is owned by
    # platform_view_owner, which can read only the columns its views need, so platform_reader
    # needs no privilege on any tenant table. Never grant platform_reader direct table access.
    op.execute("CREATE SCHEMA platform")
    op.execute("REVOKE ALL ON SCHEMA platform FROM PUBLIC")
    op.execute("GRANT USAGE, CREATE ON SCHEMA platform TO platform_view_owner")
    op.execute("GRANT USAGE ON SCHEMA platform TO platform_reader")

    columns = ", ".join(INGESTION_VIEW_DOCUMENT_COLUMNS)
    op.execute(f"GRANT SELECT ({columns}) ON assay.documents TO platform_view_owner")
    op.execute("GRANT SELECT (id, name) ON assay.tenants TO platform_view_owner")
    op.execute(
        "GRANT SELECT (tenant_id, document_id) ON assay.document_parts TO platform_view_owner"
    )
    for table in ("documents", "tenants", "document_parts"):
        _policy(
            "platform_view_owner_all",
            table,
            "SELECT",
            "platform_view_owner",
            using="true",
            check=None,
        )

    # Section 7: metadata only. No file_name.
    op.execute(INGESTION_VIEW)
    op.execute("REVOKE ALL ON platform.platform_ingestion_v FROM PUBLIC")
    op.execute("GRANT SELECT ON platform.platform_ingestion_v TO platform_reader")
    # Last: the grants above carry over to the new owner.
    op.execute("ALTER VIEW platform.platform_ingestion_v OWNER TO platform_view_owner")

    # audit_log: monthly partitions (section 7a). The default partition catches anything
    # outside the created months, so an audit insert never fails for want of a partition.
    op.execute("CREATE TABLE assay.audit_log_default PARTITION OF assay.audit_log DEFAULT")
    op.execute(AUDIT_PARTITION_FUNCTION)
    op.execute("REVOKE ALL ON FUNCTION assay.ensure_audit_log_partitions(integer) FROM PUBLIC")
    op.execute("SELECT assay.ensure_audit_log_partitions(12)")


def _security_downgrade() -> None:
    op.execute("DROP FUNCTION IF EXISTS assay.ensure_audit_log_partitions(integer)")
    op.execute("DROP VIEW IF EXISTS platform.platform_ingestion_v")
    op.execute("DROP SCHEMA IF EXISTS platform")
